patch:
diff --git a/repro/cross-drive-ignore.js b/repro/cross-drive-ignore.js
new file mode 100644
index 0000000..cb7bc7b
--- /dev/null
+++ b/repro/cross-drive-ignore.js
@@ -0,0 +1,46 @@
+/*
+ * Simulated-Windows repro for "files on a different drive are not ignored".
+ * Switches Node's `path` to win32 semantics and fakes cwd = C:\Project,
+ * then lints F:\foo.js via Linter#verify and ESLint#lintText/isPathIgnored.
+ */
+"use strict";
+const Module = require("node:module");
+const path = require("node:path");
+
+process.chdir(path.join(__dirname, "..")); // real cwd for module loading
+const origLoad = Module._load;
+Module._load = function(request, ...rest) {
+    if (request === "path" || request === "node:path") return path.win32;
+    return origLoad.call(this, request, ...rest);
+};
+const FAKE_CWD = "C:\\Project";
+process.cwd = () => FAKE_CWD;
+
+const { Linter, ESLint } = require("../lib/api");
+const file = "F:\\foo.js";
+const code = "foo();\n";
+const rules = { "no-undef": "error" };
+
+(async () => {
+    const linter = new Linter({ configType: "flat", cwd: FAKE_CWD });
+    const linterMsgs = linter.verify(code, { rules }, file);
+    console.log("Linter#verify(F:\\foo.js) messages:", linterMsgs.map(m => `${m.ruleId ?? "-"}: ${m.message}`));
+
+    const sameDrive = linter.verify(code, { rules }, "C:\\Project\\foo.js");
+    console.log("Linter#verify(C:\\Project\\foo.js) messages:", sameDrive.map(m => `${m.ruleId ?? "-"}: ${m.message}`));
+
+    const otherDir = linter.verify(code, { rules }, "C:\\other\\foo.js");
+    console.log("Linter#verify(C:\\other\\foo.js) messages (control, same drive outside cwd):", otherDir.map(m => `${m.ruleId ?? "-"}: ${m.message}`));
+    console.log("path.relative(cwd, F:\\foo.js) =", JSON.stringify(path.win32.relative(FAKE_CWD, file)));
+
+    const eslint = new ESLint({ cwd: FAKE_CWD, overrideConfigFile: true, overrideConfig: { rules } });
+    console.log("ESLint#isPathIgnored(F:\\foo.js):", await eslint.isPathIgnored(file));
+    console.log("ESLint#isPathIgnored(C:\\other\\foo.js) (control):", await eslint.isPathIgnored("C:\\other\\foo.js"));
+    const [r] = await eslint.lintText(code, { filePath: file, warnIgnored: true });
+    console.log("ESLint#lintText(filePath F:\\foo.js):", r.messages.map(m => `${m.ruleId ?? "-"}: ${m.message}`));
+
+    const bug = linterMsgs.some(m => m.ruleId === "no-undef") || r.messages.some(m => m.ruleId === "no-undef");
+    console.log(bug ? "\nBUG REPRODUCED: F:\\foo.js (outside cwd C:\\Project, other drive) was linted instead of ignored"
+                    : "\nNot reproduced: F:\\foo.js was ignored");
+    process.exitCode = bug ? 1 : 0;
+})();
